package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.digest.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for SubLine#intersection.
 */
public class SubLine_intersection_TriageGen3Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_IncludeEndPoints_Success() throws Exception {
        // Create two intersecting sublines that meet at an endpoint
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (2,0,0) to (2,2,0)
        SubLine subLine2 = new SubLine(new Vector3D(2, 0, 0), new Vector3D(2, 2, 0));

        // Intersection is at (2,0,0)
        Vector3D result = subLine1.intersection(subLine2, true);

        assertEquals(2.0, result.getX(), EPSILON);
        assertEquals(0.0, result.getY(), EPSILON);
        assertEquals(0.0, result.getZ(), EPSILON);
    }

    @Test
    public void testIntersection_IncludeEndPoints_Inside() throws Exception {
        // Line 1: (0,0,0) to (5,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(5, 0, 0));
        // Line 2: (1, -1, 0) to (1, 1, 0)
        SubLine subLine2 = new SubLine(new Vector3D(1, -1, 0), new Vector3D(1, 1, 0));

        // Intersection is at (1,0,0) which is inside both
        Vector3D result = subLine1.intersection(subLine2, true);

        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(0.0, result.getY(), EPSILON);
        assertEquals(0.0, result.getZ(), EPSILON);
    }

    @Test
    public void testIntersection_IncludeEndPoints_Outside() throws Exception {
        // Line 1: (0,0,0) to (1,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(1, 0, 0));
        // Line 2: (2, -1, 0) to (2, 1, 0)
        SubLine subLine2 = new SubLine(new Vector3D(2, -1, 0), new Vector3D(2, 1, 0));

        // Lines intersect at (2,0,0) in infinite space, but (2,0,0) is outside subLine1
        Vector3D result = subLine1.intersection(subLine2, true);

        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_Success() throws Exception {
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (1, -1, 0) to (1, 1, 0)
        SubLine subLine2 = new SubLine(new Vector3D(1, -1, 0), new Vector3D(1, 1, 0));

        // Intersection (1,0,0) is strictly inside both
        Vector3D result = subLine1.intersection(subLine2, false);

        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(0.0, result.getY(), EPSILON);
        assertEquals(0.0, result.getZ(), EPSILON);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_AtBoundary_ReturnsNull() throws Exception {
        // Line 1: (0,0,0) to (1,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(1, 0, 0));
        // Line 2: (1, 0, 0) to (1, 1, 0)
        SubLine subLine2 = new SubLine(new Vector3D(1, 0, 0), new Vector3D(1, 1, 0));

        // Intersection is (1,0,0), which is an endpoint. 
        // If includeEndPoints is false, it should return null because it's not INSIDE.
        Vector3D result = subLine1.intersection(subLine2, false);

        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_Outside() throws Exception {
        // Line 1: (0,0,0) to (1,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(1, 0, 0));
        // Line 2: (2, -1, 0) to (2, 1, 0)
        SubLine subLine2 = new SubLine(new Vector3D(2, -1, 0), new Vector3D(2, 1, 0));

        Vector3D result = subLine1.intersection(subLine2, false);

        assertNull(result);
    }
}
